-- 検索が日本語で正しく効くようにする
--
-- 1. 照合順序を utf8mb4_ja_0900_as_cs にする
--    今までの utf8mb4_unicode_ci は濁点とカナの別を無視するので、
--    「ばし」で検索しても「はし」が出ていた。as_cs は濁点を区別し、
--    ひらがなとカタカナは同じものとして扱う。日本語の検索としてはこれが自然。
--
-- 2. 既にある名前を合成済み(NFC)にそろえる
--    macOS で作ったファイル名は「カ」+「゙」の分解形で入る。利用者が打つのは
--    合成済みの「ガ」なので、そのままでは見た目が同じでも引けない。
--    並び順を先に変えてから、分解形を合成形に置き換える。
--    比較する文字は照合順序を明示する。列と食い違うと MySQL が混在を嫌うため。

ALTER TABLE `review_jobs` MODIFY `name` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_ja_0900_as_cs NOT NULL;
ALTER TABLE `review_documents` MODIFY `filename` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_ja_0900_as_cs NOT NULL;
ALTER TABLE `tool_configurations` MODIFY `name` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_ja_0900_as_cs NOT NULL;
ALTER TABLE `prompt_templates` MODIFY `name` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_ja_0900_as_cs NOT NULL;
ALTER TABLE `check_list_sets` MODIFY `name` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_ja_0900_as_cs NOT NULL;
ALTER TABLE `checklist_documents` MODIFY `filename` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_ja_0900_as_cs NOT NULL;

